let dashLoadPromise=null,dashPlayer=null,playerEngine='none';
let channelBannerTimer=null;let tvBannerAbort=new AbortController();
function isDash(url){return /\.mpd(?:[?#]|$)/i.test(url)}
function sourceKind(url){return isDash(url)?'MPEG-DASH':isHls(url)?'HLS':'Video'}
function loadDashLibrary(){if(window.dashjs?.MediaPlayer)return Promise.resolve(window.dashjs);if(dashLoadPromise)return dashLoadPromise;dashLoadPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=DASH_CDN;script.crossOrigin='anonymous';script.onload=()=>window.dashjs?.MediaPlayer?resolve(window.dashjs):reject(Error('DASH library loaded but is unavailable'));script.onerror=()=>reject(Error('DASH player library could not be downloaded; check your connection or content blocker'));document.head.append(script)}).catch(e=>{dashLoadPromise=null;throw e});return dashLoadPromise}

const pages=[['dashboard','◈','Dashboard'],['iptv','▣','IPTV & Live TV'],['ai','✦','AI Assistant'],['entertainment','▶','Entertainment'],['apps','▦','App Centre'],['home','⌂','Smart Home'],['settings','⚙','Settings']];
const defaults={streamHealth:{},theme:'dark',name:'Home',devices:{'Living room lights':true,'Kitchen lights':false,'Heating':true,'Garden lights':false},favourites:[],channels:[],chat:[],epg:[],filterGroup:'All',onlyFavourites:false,dashboardLayout:['welcome','clock','television','entertainment','assistant','devices','shortcuts','overview'],dashboardHidden:[],dashboardCompact:false,watchlist:[],tunerFavouritesOnly:false};
let state;try{state={...defaults,...JSON.parse(localStorage.getItem('homeos01')||'{}')}}catch{state={...defaults}};state.epg=Array.isArray(state.epg)?state.epg:[];state.channels=Array.isArray(state.channels)?state.channels:[];state.favourites=Array.isArray(state.favourites)?state.favourites:[];state.streamHealth=state.streamHealth&&typeof state.streamHealth==='object'?state.streamHealth:{};state.watchlist=Array.isArray(state.watchlist)?state.watchlist:[];state.tunerFavouritesOnly=!!state.tunerFavouritesOnly;
