function navigate(p){page=p;selected=-1;playingURL='';render();history.replaceState(null,'','#'+p)}
function render(){if(activeVideo)clearPlayback();document.body.classList.toggle('theme-light',state.theme==='light');$('menu').innerHTML=pages.map(([id,ic,label])=>`<button class="nav ${id===page?'active':''}" data-nav="${id}" aria-current="${id===page?'page':'false'}"><span>${ic}</span>${label}</button>`).join('');$('heading').textContent=pages.find(x=>x[0]===page)?.[2]||'Dashboard';$('sectionLabel').textContent='HomeOS / '+page;const views={dashboard,iptv,ai,entertainment,apps,home,settings};$('content').innerHTML=(views[page]||dashboard)();document.querySelectorAll('[data-nav]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.nav)));wire();clock();}
const DASHBOARD_WIDGETS=[
 ['welcome','Welcome'],['clock','Clock & date'],['television','Live television'],['entertainment','Entertainment'],['assistant','AI assistant'],['devices','Smart home'],['shortcuts','Quick launch'],['overview','System overview']
];
function dashboard(){
 const order=Array.isArray(state.dashboardLayout)?state.dashboardLayout:defaults.dashboardLayout;
 const hidden=Array.isArray(state.dashboardHidden)?state.dashboardHidden:[];
 const safeOrder=[...new Set([...order,...DASHBOARD_WIDGETS.map(x=>x[0])])].filter(x=>DASHBOARD_WIDGETS.some(w=>w[0]===x));
 const count=Object.values(state.devices).filter(Boolean).length;
 const widgets={
 welcome:()=>`<section class="hero-home"><div><div class="eyebrow">WELCOME TO HOMEOS</div><h2>Welcome to ${escapeHTML(state.name)}</h2><p>Your television, entertainment and connected home, beautifully together.</p><div class="chips"><button class="btn primary" data-go="iptv">▣ Watch TV</button><button class="btn" data-go="entertainment">▶ Entertainment</button></div></div><div class="hero-art" aria-hidden="true">⌂</div></section>`,
 clock:()=>card('Time & date',`<div class="metric" id="bigclock">--:--</div><p class="muted" id="today"></p><span class="subtle-label">Local time on this device · Weather integration planned</span>`),
 television:()=>card('Live TV',`<div class="metric">${channels().length}</div><p class="muted">${state.channels.length?'Imported channels':'Demo channels'} available in your browser</p><button class="btn" data-go="iptv">Open TV guide →</button>`),
 entertainment:()=>card('Entertainment',`<p class="muted">Your music, films and personal media in one place.</p><button class="btn" data-go="entertainment">Open entertainment →</button>`),
 assistant:()=>card('AI assistant',`<p class="muted">Explore the assistant prototype. Responses are simulated, not connected to ChatGPT.</p><button class="btn" data-go="ai">Open assistant →</button>`),
 devices:()=>card('Home at a glance',`<div class="metric">${count} <span class="muted" style="font-size:17px">/ ${Object.keys(state.devices).length} on</span></div><p class="muted">Demonstration devices only</p><button class="btn" data-go="home">View devices →</button>`),
 shortcuts:()=>card('Quick launch',`<div class="shortcut-grid">${[['▣','Television','iptv'],['▶','Media','entertainment'],['✦','Assistant','ai'],['⌂','Home','home'],['▦','Apps','apps'],['⚙','Settings','settings']].map(([icon,label,target])=>`<button class="shortcut" data-go="${target}"><span aria-hidden="true">${icon}</span>${label}</button>`).join('')}</div>`,'large'),
 overview:()=>card('System overview',`<div class="stack"><div class="row"><span>HomeOS version</span><strong>${APP_VERSION}</strong></div><div class="row"><span>Playlist</span><strong>${state.channels.length?'Imported':'Demo'}</strong></div><div class="row"><span>Assistant</span><strong>Demo mode</strong></div><div class="row"><span>Device controls</span><strong>Simulated</strong></div></div><p class="muted" style="font-size:12px">HomeOS currently runs locally in your browser; no physical devices are controlled.</p>`)
 };
 return `<div class="dashboard-top"><div><div class="eyebrow">HOMEOS / DASHBOARD</div><h2 class="dash-title">Your space</h2><p class="muted">Your world, one beautiful space.</p></div><button class="btn" id="customiseDashboard" aria-expanded="false">⚙ Customise</button></div><section class="card dashboard-editor hidden" id="dashboardEditor"><h2>Customise your dashboard</h2><p class="muted">Show or hide widgets, change their order, or choose a compact layout. Changes are saved on this device.</p><div class="stack">${safeOrder.map((id,i)=>`<div class="widget-editor-row"><label class="check-inline"><input type="checkbox" data-widget-toggle="${id}" ${hidden.includes(id)?'':'checked'}> ${escapeHTML(DASHBOARD_WIDGETS.find(w=>w[0]===id)[1])}</label><div class="chips"><button class="btn" data-widget-move="${id}" data-direction="up" ${i===0?'disabled':''} aria-label="Move ${id} up">↑</button><button class="btn" data-widget-move="${id}" data-direction="down" ${i===safeOrder.length-1?'disabled':''} aria-label="Move ${id} down">↓</button></div></div>`).join('')}</div><label class="check-inline" style="margin:14px 0"><input type="checkbox" id="dashboardCompact" ${state.dashboardCompact?'checked':''}> Compact widget spacing</label><button class="btn" id="dashboardReset">Restore default dashboard</button></section><div class="dashboard-grid ${state.dashboardCompact?'compact':''}">${safeOrder.filter(id=>!hidden.includes(id)).map(id=>`<div class="dashboard-item ${id==='welcome'?'wide':''}" data-widget="${id}">${widgets[id]()}</div>`).join('')||'<div class="card">All widgets are hidden. Select Customise to show them.</div>'}</div>`;
}

