function tunerChannels(){
 const q=($('quickChannelSearch')?.value||'').trim().toLowerCase();
 return channels().map((c,i)=>({c,i})).filter(({c})=>(!q||c.name.toLowerCase().includes(q))&&(!state.tunerFavouritesOnly||state.favourites.includes(c.url)));
}
function updateSelectedFavourite(){const c=channels()[selected],b=$('fav');if(b)b.textContent=c&&state.favourites.includes(c.url)?'★ Remove favourite':'☆ Favourite selected'}
function refreshTuner(){
 const sel=$('quickChannel');if(!sel)return;
 const items=tunerChannels();sel.innerHTML='<option value="">Select a channel…</option>'+items.map(({c,i})=>`<option value="${i}">${escapeHTML(c.name)}</option>`).join('');
 sel.value=items.some(x=>x.i===selected)?String(selected):'';
 updateSelectedFavourite();if($('tunerHint'))$('tunerHint').textContent=`${items.length} channels available · Tap the video to show the information banner`;
 if($('quickFav')){$('quickFav').textContent=state.tunerFavouritesOnly?'★ Favourites':'☆ Favourites';$('quickFav').setAttribute('aria-pressed',String(!!state.tunerFavouritesOnly))}
}
function stepChannel(direction){const items=tunerChannels();if(!items.length)return;const pos=items.findIndex(x=>x.i===selected);const next=items[(pos<0?(direction>0?0:items.length-1):(pos+direction+items.length)%items.length)];play(next.i)}
function showChannelBanner(channel){
 if(channelBannerTimer){clearTimeout(channelBannerTimer);channelBannerTimer=null}
 const player=$('player');if(!player)return;
 let banner=$('tvChannelBanner');if(!banner){banner=document.createElement('div');banner.id='tvChannelBanner';banner.className='tv-channel-banner';banner.setAttribute('role','status');banner.setAttribute('aria-live','polite');player.append(banner)}
 const index=channels().findIndex(c=>c.url===channel.url);const number=index>=0?String(index+1).padStart(3,'0'):'';
 banner.innerHTML=`<span class="tv-channel-number">${number}</span><span class="tv-channel-name">${escapeHTML(channel.name)}</span><span class="tv-channel-live">LIVE</span>`;
 banner.classList.remove('tv-banner-hidden');channelBannerTimer=setTimeout(()=>{banner.classList.add('tv-banner-hidden');channelBannerTimer=null},5000);
}
function drawChannels(){let list=$('channelList');if(!list)return;let query=$('filterChannels').value.toLowerCase();let cs=channels();let filtered=cs.map((c,i)=>({c,i})).filter(({c})=>[c.name,c.group||''].some(t=>t.toLowerCase().includes(query))&&(state.filterGroup==='All'||(c.group||'Uncategorised')===state.filterGroup)&&(!state.onlyFavourites||state.favourites.includes(c.url))&&(!$('hideUnreliable')?.checked||state.streamHealth[c.url]?.status!=='unreliable'));$('channelCount').textContent=`${filtered.length} / ${cs.length} entries`;refreshTuner();list.innerHTML=filtered.slice(0,500).map(({c,i})=>{let h=state.streamHealth[c.url];let tag=h?.status==='working'?'✓ Working':h?.status==='unreliable'?'⚠ Unreliable':h?.status==='failed'?'× Failed':'Not tested';return `<button class="channel ${selected===i?'active':''}" data-channel="${i}"><span>${state.favourites.includes(c.url)?'★ ':''}${escapeHTML(c.name)}</span><span class="muted" style="display:block;font-size:12px">${escapeHTML(c.group||'Uncategorised')} · ${isHls(c.url)?'HLS':'Video'} · ${tag}</span></button>`}).join('')||'<p class="muted">No matching channels</p>';list.querySelectorAll('[data-channel]').forEach(b=>b.addEventListener('click',()=>play(Number(b.dataset.channel))));}
function showGuide(){const view=$('epgView');if(!view)return;const c=channels()[selected];if(!c){view.innerHTML='<p class="muted">Select a channel to view its schedule.</p>';return}let now=Date.now();let shows=state.epg.filter(p=>p.id&&p.id===c.id).sort((a,b)=>a.start-b.start);let current=shows.find(p=>p.start<=now&&p.stop>now),next=shows.find(p=>p.start>now);const fmt=t=>new Date(t).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});view.innerHTML=shows.length?`<h3>${escapeHTML(c.name)}</h3>`+[current,next].filter(Boolean).map((p,i)=>`<div class="device"><div><strong>${i===0&&current?'Now':'Next'}: ${escapeHTML(p.title)}</strong><div class="muted">${fmt(p.start)}–${fmt(p.stop)}</div></div></div>`).join(''):'<p class="muted">No matching programmes. Check the channel tvg-id and XMLTV channel ID.</p>';if($('nowPlaying'))$('nowPlaying').textContent=current?'Now: '+current.title:'';}
let sourceCheck=null,terminalFailure=false;
let sessionEvents=[],lastFailure='',activeVideo=null,activeTimer=null,activeGeneration=0,stallSince=0,lastProgressAt=0,lastVideoTime=0,recoveryCount=0,startedAt=0,playbackTimer=null;
function clearPlayback(){tvBannerAbort.abort();tvBannerAbort=new AbortController();if(channelBannerTimer){clearTimeout(channelBannerTimer);channelBannerTimer=null}activeGeneration++;sourceCheck=null;terminalFailure=false;if(dashPlayer){try{dashPlayer.reset()}catch(e){console.warn('DASH cleanup',e)}dashPlayer=null}playerEngine='none';if(activeTimer)clearInterval(activeTimer);activeTimer=null;if(playbackTimer)clearTimeout(playbackTimer);playbackTimer=null;if(activeVideo){activeVideo.pause();activeVideo.removeAttribute('src');activeVideo.load();activeVideo=null}}
