const failed=(message)=>{if(!current()||terminalFailure)return;terminalFailure=true;lastFailure=message;log('error',message);setStatus(message);diagnostics('Playback failed');health(c.url,'failed')};
const attemptAutoplay=()=>{if(!current()||terminalFailure)return;const attempt=video.play();if(attempt&&typeof attempt.catch==='function')attempt.catch(e=>{if(!current()||terminalFailure)return;if(e.name==='NotAllowedError'){setStatus('Safari requires a tap to start this channel. Use the video Play button.');log('autoplay-blocked','Browser requires user gesture')}else if(e.name!=='AbortError'){log('play-rejected',e.name||'Playback unavailable')}})};
if(hls&&!video.canPlayType('application/vnd.apple.mpegurl')){setStatus('Native HLS is unavailable in this browser. Try Safari on iPhone.');player.innerHTML='<p class="muted" style="padding:18px">HLS not supported natively in this browser.</p>';drawChannels();showGuide();return}
