activeTimer=setInterval(()=>{if(!current()||terminalFailure)return;let now=Date.now();if(!video.paused&&!video.ended&&wasPlaying&&now-lastProgressAt>12000){if(recoveryCount<1){recoveryCount++;log('recovery','one reload attempt');setStatus('Stream interrupted. Attempting one recovery…');diagnostics('Recovery attempt');lastProgressAt=now;stallSince=0;video.load();video.play().catch(()=>setStatus('Automatic recovery blocked. Tap Retry stream.'))}else{setStatus('Stream stopped progressing after recovery. Tap Retry stream or try another channel.');diagnostics('Unreliable stream');if(!lastFailure){lastFailure='No playback progress after recovery';log('recovery-failed',lastFailure)}if(state.streamHealth[c.url]?.status!=='unreliable')health(c.url,'unreliable')}}else if(now-lastProgressAt<6000&&wasPlaying&&!video.paused){diagnostics('Playing')}} ,2000);
player.append(video);if(!dash)attemptAutoplay();showChannelBanner(c);player.addEventListener('click',e=>{if(e.target===player||e.target===video)showChannelBanner(c)},{signal:tvBannerAbort.signal});setStatus(dash?'Initialising DASH player…':'Tuning to '+c.name+'…');diagnostics('Selected');drawChannels();showGuide();
