function parseM3u(text){let lines=text.replace(/^\uFEFF/,'').split(/\r?\n/).map(s=>s.trim());if(!lines[0]?.startsWith('#EXTM3U'))throw Error('Playlist must begin with #EXTM3U');let result=[],label='',group='',id='';for(const line of lines){if(line.startsWith('#EXTINF:')){label=line.includes(',')?line.slice(line.indexOf(',')+1).trim():'Unnamed channel';group=line.match(/group-title="([^"]*)"/i)?.[1]||'Uncategorised';id=line.match(/tvg-id="([^"]*)"/i)?.[1]||''}else if(line&&!line.startsWith('#')){if(!/^https:\/\//i.test(line))continue;result.push({name:label||`Channel ${result.length+1}`,url:line,group,id});label='';group='';id='';if(result.length>=500)break}}return result}
function xmltvDate(t){let m=String(t||'').match(/^(\d{4})(\d\d)(\d\d)(\d\d)(\d\d)(\d\d)?\s*([+-]\d{4})?/);if(!m)return NaN;let z=m[7]||'+0000',offset=(z[0]==='-'?-1:1)*(Number(z.slice(1,3))*60+Number(z.slice(3,5)));return Date.UTC(+m[1],+m[2]-1,+m[3],+m[4],+m[5],+(m[6]||0))-offset*60000}
function parseXmltv(text){let doc=new DOMParser().parseFromString(text,'application/xml');if(doc.querySelector('parsererror'))throw Error('Invalid XMLTV XML');let programmes=[...doc.getElementsByTagName('programme')];if(programmes.length>5000)throw Error('Guide too large (maximum 5,000 programmes)');return programmes.map(p=>({id:p.getAttribute('channel')||'',title:p.getElementsByTagName('title')[0]?.textContent?.trim()||'Untitled programme',start:xmltvDate(p.getAttribute('start')),stop:xmltvDate(p.getAttribute('stop'))})).filter(p=>Number.isFinite(p.start)&&Number.isFinite(p.stop)&&p.stop>p.start)}
function setPlaylist(text){clearPlayback();let cs=parseM3u(text);if(!cs.length)throw Error('No valid HTTPS channel URLs found');state.channels=cs;state.filterGroup='All';selected=-1;save();render();$('importStatus').textContent=`Imported ${cs.length} channels (maximum 500).`}
function ai(){return `<div class="grid">${card('Conversation',`<div class="chat" id="chatLog" aria-live="polite">${(state.chat.length?state.chat:[{who:'assistant',text:'Hello! This is the HomeOS AI interface demo. Try asking about the dashboard, IPTV or smart home.'}]).map(m=>`<div class="bubble ${m.who==='user'?'user':''}">${escapeHTML(m.text)}</div>`).join('')}</div><form id="chatForm" class="row" style="margin-top:12px"><input id="chatInput" class="field" style="flex:1" required maxlength="500" placeholder="Ask a question"><button class="btn primary" type="submit">Send</button></form><div class="chips" style="margin-top:12px"><button class="btn" data-ai-prompt="How do I watch live TV?">Live TV help</button><button class="btn" data-ai-prompt="How do I use favourites?">Favourites help</button><button class="btn" data-ai-prompt="What can HomeOS do?">HomeOS features</button></div><div class="row" style="margin-top:10px"><button class="btn" id="clearChat">Clear conversation</button><span class="pill">Offline simulated AI</span></div>`,'large')}${card('Integration status',`${note('This prototype does NOT connect to OpenAI or store API keys. Replies are rule-based simulations.')}<p class="muted">Future: secured backend, authenticated sessions, OpenAI API, speech-to-text, text-to-speech and explicit permission for home controls.</p>`)} </div>`}
function reply(t){let s=t.toLowerCase();if(s.includes('favourite')||s.includes('favorite'))return 'Open Live TV, select a channel and tap its star to save it. Use the Favourites selector beneath the player to browse saved channels. Next and Previous follow your selected group.';if(s.includes('homeos')||s.includes('features'))return 'HomeOS includes a customisable dashboard, IPTV player, entertainment service shortcuts, local media playback and simulated smart-home controls. This assistant is a rule-based demonstration, not live ChatGPT.';if(s.includes('iptv')||s.includes('tv'))return 'Open IPTV & Live TV to import an M3U playlist or test sample video playback.';if(s.includes('light')||s.includes('home'))return 'The Smart Home page contains simulated switches. No real household devices are connected.';if(s.includes('app')||s.includes('install'))return 'The App Centre shows demonstration shortcuts. APK installation requires a native Android implementation.';if(s.includes('time'))return 'Your device reports '+new Date().toLocaleTimeString()+'.';return 'This is a simulated reply, not ChatGPT. In a later version, a secure API integration will provide real AI conversations.'}
