function entertainment(){return `<div class="entertainment-hub"><section class="media-hero"><div class="eyebrow">HOMEOS / ENTERTAINMENT</div><h2>Your entertainment, beautifully together.</h2><p>Discover your services, save favourites and play local videos. External services open in their own websites.</p><div class="chips"><button class="btn primary" data-go="iptv">▣ Live TV</button><a class="btn" href="https://app.plex.tv" target="_blank" rel="noopener noreferrer">▶ Open Plex ↗</a></div></section><div class="media-toolbar"><input id="mediaSearch" class="field" type="search" placeholder="Search your services…" aria-label="Search entertainment services"><div class="media-tabs" id="mediaTabs"><button class="btn primary" data-media-filter="all">Explore</button><button class="btn" data-media-filter="saved">★ Watchlist</button><button class="btn" data-media-filter="UK television">UK TV</button><button class="btn" data-media-filter="Library">Library</button></div></div><div class="media-section-head"><h2>Explore entertainment</h2><span id="mediaCount" class="muted"></span></div><div class="media-grid" id="mediaGrid"></div>${card('Play a video from this device',`<p class="muted">Select a video file on your device. Playback stays in this browser and the file is not uploaded.</p><input class="field" type="file" id="localVideo" accept="video/*"><div class="player" id="localPlayer" style="margin-top:12px;min-height:150px">Choose a local video to begin</div>`)}<p class="muted media-disclaimer">HomeOS does not supply or claim access to third-party films. Some services require an account, licence or their own app. The watchlist saves service shortcuts, not viewing history.</p></div>`}
