async function checkSelectedSource(){
 const c=channels()[selected],gen=activeGeneration,button=$('checkSource'),message=$('sourceCheckStatus');
 if(!c){if(message)message.textContent='Select a channel first.';return}
 if(button)button.disabled=true;if(message)message.textContent='Checking source access from this browser…';
 const started=Date.now();let outcome={result:'unknown',httpStatus:null,contentType:null,elapsedMs:null,detail:''};
 try{
  const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);
  try{const response=await fetch(c.url,{method:'GET',mode:'cors',credentials:'omit',cache:'no-store',signal:controller.signal});
   outcome.httpStatus=response.status;outcome.contentType=response.headers.get('content-type');
   outcome.result=response.ok?'HTTP response accessible':'HTTP error';
   outcome.detail=response.ok?'Browser permitted a CORS response. This does not prove media segments or codecs work.':'The server returned HTTP '+response.status+'.';
   await response.body?.cancel().catch(()=>{});
  }finally{clearTimeout(timer)}
 }catch(e){outcome.result=e.name==='AbortError'?'Timeout':'Browser fetch blocked or failed';outcome.detail=e.name==='AbortError'?'No CORS-accessible response within 8 seconds.':'Network failure, CORS restrictions or server refusal; browser security does not reveal which.'}
 outcome.elapsedMs=Date.now()-started;
 if(gen!==activeGeneration)return;
 sourceCheck=outcome;if(message)message.textContent=outcome.result+': '+outcome.detail;
 if(button)button.disabled=false;
}
